import java.util.*;

public class GraphAlgorithms {
    // Topological Sort using Kahn's Algorithm (BFS-based)
    public static List<Integer> topologicalSort(int numVertices, List<List<Integer>> adjList) {
        int[] inDegree = new int[numVertices];
        for (int u = 0; u < numVertices; u++) {
            for (int v : adjList.get(u)) {
                inDegree[v]++;
            }
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < numVertices; i++) {
            if (inDegree[i] == 0) {
                queue.offer(i);
            }
        }

        List<Integer> topologicalOrder = new ArrayList<>();
        while (!queue.isEmpty()) {
            int curr = queue.poll();
            topologicalOrder.add(curr);

            for (int neighbor : adjList.get(curr)) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        if (topologicalOrder.size() != numVertices) {
            throw new IllegalStateException("Graph contains a cycle; topological sort impossible.");
        }

        return topologicalOrder;
    }
}
